<script lang="ts">
 import type {RegisterFilterRequest} from './register-filter';
 import {openReportLookup} from './report-settings';
 import {Check,X,ListChecks} from "./icons";
 export let request:RegisterFilterRequest;export let language:'ru'|'ro'|"en";export let onclose:()=>void;
 let filters=structuredClone(request.filters);
 const t=(ru:string,ro:string)=>language==='ru'?ru:ro;
 function choose(i:number){const filter=filters[i];openReportLookup({id:request.id+'-value-'+i,parentId:'registerfilter:'+request.id,label:request.labels[i],items:request.items[i].map((v,j)=>({id:v,code:String(j+1),name:v})),selected:filter.values,multiple:filter.comparison==='in'||filter.comparison==='not-in',onchoose:ids=>{filters[i]={...filter,enabled:true,values:ids};filters=[...filters];}});}
</script>
<div class="register-filter"><nav><button onclick={()=>filters=filters.map(f=>({...f,enabled:true}))}><Check size={15}/>{t('Установить все пометки','Selectează toate')}</button><button onclick={()=>filters=filters.map(f=>({...f,enabled:false}))}><X size={15}/>{t('Снять все пометки','Deselectează toate')}</button><button onclick={()=>filters=filters.map(f=>({...f,enabled:f.values.some(Boolean)}))}><ListChecks size={15}/>{t('Отметить заполненные поля','Selectează câmpurile completate')}</button></nav>
<div class="filter-scroll"><table><thead><tr><th></th><th>{t('Отбор','Filtru')}</th><th>{t('Тип сравнения','Tip comparație')}</th><th>{t('Значение','Valoare')}</th></tr></thead><tbody>{#each filters as f,i}<tr><td><input type="checkbox" bind:checked={f.enabled} aria-label={request.labels[i]}/></td><td>{request.labels[i]}</td><td><select aria-label={t('Тип сравнения','Tip comparație')} bind:value={f.comparison}><option value="eq">{t('Равно','Egal')}</option><option value="ne">{t('Не равно','Diferit')}</option>{#if request.dateColumns.includes(f.column)}<option value="lt">{t('Меньше','Mai mic')}</option><option value="le">{t('Меньше или равно','Mai mic sau egal')}</option><option value="gt">{t('Больше','Mai mare')}</option><option value="ge">{t('Больше или равно','Mai mare sau egal')}</option>{:else}<option value="in">{t('В списке','În listă')}</option><option value="not-in">{t('Не в списке','Nu este în listă')}</option>{/if}</select></td><td>{#if request.dateColumns.includes(f.column)}<input type="date" aria-label={request.labels[i]} value={f.values[0]||''} onchange={e=>{f.values=[e.currentTarget.value];f.enabled=true;filters=[...filters];}}/>{:else}<div class="value-field"><input readonly aria-label={request.labels[i]} value={f.values.join('; ')}/><button aria-label={t('Выбрать','Selectează')} onclick={()=>choose(i)}>…</button><button aria-label={t('Очистить','Golește')} onclick={()=>{f.values=[];filters=[...filters];}}><X size={14}/></button></div>{/if}</td></tr>{/each}</tbody></table></div>
<footer><button class="button secondary" onclick={()=>{request.onapply(structuredClone(filters));onclose();}}><Check size={16}/>OK</button><button class="button secondary" onclick={onclose}><X size={16}/>{t('Отмена','Anulează')}</button></footer></div>
<style>.register-filter{display:flex;flex-direction:column;gap:10px;padding:12px;min-height:100%;box-sizing:border-box}nav{display:flex;flex-wrap:wrap;gap:6px}nav button,.value-field button{background:transparent;border:0;color:var(--text);display:flex;align-items:center;gap:6px;padding:7px}.filter-scroll{overflow:auto;flex:1}table{width:100%;border-collapse:collapse}th{text-align:left;background:#80808020}th,td{padding:4px 7px;border:1px solid var(--border)}td:first-child{width:24px}td:nth-child(2){min-width:150px}td:nth-child(3){width:170px}td:last-child{min-width:180px}select,input[type=date]{width:100%;height:34px;box-sizing:border-box}.value-field{display:flex;min-width:0}.value-field input{width:100%;min-width:0;height:34px;box-sizing:border-box}.value-field button{flex:0 0 32px;justify-content:center}footer{display:flex;justify-content:flex-end;gap:8px;margin-top:auto}</style>
